<?php $pageTitle='Kasir / POS';require __DIR__.'/../partials/header.php';require __DIR__.'/../partials/sidebar.php';?><main class="main"><div class="container-fluid"><?php require __DIR__.'/../partials/navbar.php';?><?php if($m=flash('error')):?><div class="alert alert-danger"><?=e($m)?></div><?php endif;?><div class="row g-4"><div class="col-lg-8"><div class="product-grid"><?php foreach($produk as $p):?><button class="product-card" type="button" onclick='addProduct(<?=json_encode($p)?>)'><span class="product-tag">STOK <?=$p['stok']?></span><strong><?=e($p['nama'])?></strong><small><?=rupiah($p['harga'])?></small></button><?php endforeach;?></div></div><div class="col-lg-4"><div class="cart card-shell"><div class="section-title">Keranjang <span id="count" class="badge">0</span></div><div id="cart"></div><div class="cart-total"><span>Total</span><strong id="total">Rp 0</strong></div><form method="post" action="?page=kasir/checkout" id="checkoutForm" onsubmit="return prepareCheckout()"><label class="form-label">Member <small>(opsional)</small></label><input class="form-control mb-3" name="member_phone" placeholder="Nomor HP member"><label class="form-label">Metode pembayaran</label><select class="form-select mb-3" name="payment_method" id="paymentMethod" onchange="showPaymentInfo()"><option value="cash">Cash</option><option value="qris">QRIS</option><option value="transfer">Transfer</option></select><div id="cashInfo" class="mb-3"><label class="form-label">Uang diterima</label><div class="input-group"><span class="input-group-text">Rp</span><input class="form-control" type="text" inputmode="numeric" id="cashDisplay" placeholder="10.000" oninput="formatCash(this)"></div><input type="hidden" name="cash_received" id="cashReceived"><div class="small mt-2">Kembalian: <strong id="change">Rp 0</strong></div></div><div id="qrisInfo" class="payment-info mb-3" hidden><div class="small fw-semibold mb-2">Scan QRIS Eka Fashion</div><img src="https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=EKA-FASHION-QRIS-DEMO-TRANSACTION" alt="QRIS demo Eka Fashion" width="180" height="180"><div class="small text-muted mt-2">QR demo untuk simulasi akademik.</div></div><div id="transferInfo" class="payment-info mb-3" hidden><div class="small fw-semibold">Transfer ke rekening toko</div><div class="small text-muted">Bank Eka Fashion · 1234567890</div></div><input type="hidden" name="items" id="cartItems"><button class="btn btn-primary w-100" type="submit"><i class="bi bi-check2-circle"></i> Konfirmasi &amp; bayar</button></form></div></div></div></div><script>let cartItems=[];const money=n=>new Intl.NumberFormat('id-ID').format(n);function addProduct(p){let x=cartItems.find(i=>i.id==p.id),next=x?x.qty+1:1;if(next>Number(p.stok)){alert('Stok '+p.nama+' hanya tersedia '+p.stok+' item.');return}if(x)x.qty=next;else cartItems.push({id:p.id,nama:p.nama,harga:Number(p.harga),qty:1});renderCart()}function renderCart(){cart.innerHTML=cartItems.map(i=>`<div class="cart-item"><span>${i.nama}<small>${i.qty} × ${money(i.harga)}</small></span><b>${money(i.qty*i.harga)}</b></div>`).join('');let grand=cartItems.reduce((a,i)=>a+i.qty*i.harga,0);total.textContent='Rp '+money(grand);count.textContent=cartItems.reduce((a,i)=>a+i.qty,0);calculateChange()}function formatCash(input){let raw=input.value.replace(/\D/g,'');input.value=raw?money(Number(raw)):'';cashReceived.value=raw;calculateChange()}function showPaymentInfo(){let cash=paymentMethod.value==='cash';cashInfo.hidden=!cash;qrisInfo.hidden=paymentMethod.value!=='qris';transferInfo.hidden=paymentMethod.value!=='transfer';if(!cash){cashDisplay.value='';cashReceived.value=''}calculateChange()}function calculateChange(){let grand=cartItems.reduce((a,i)=>a+i.qty*i.harga,0),received=Number(cashReceived.value||0);change.textContent='Rp '+money(Math.max(0,received-grand))}function prepareCheckout(){if(!cartItems.length){alert('Keranjang masih kosong.');return false}let grand=cartItems.reduce((a,i)=>a+i.qty*i.harga,0);if(paymentMethod.value==='cash'&&Number(cashReceived.value||0)<grand){alert('Uang diterima belum cukup.');cashDisplay.focus();return false}document.getElementById('cartItems').value=JSON.stringify(cartItems);return confirm('Konfirmasi pembayaran '+total.textContent+' dengan metode '+paymentMethod.options[paymentMethod.selectedIndex].text+'?')}</script><?php require __DIR__.'/../partials/footer.php';?>
